import JSON5 from 'json5';
export const run = async ({ args, files }) => {
  const spaceIndex = args.indexOf('-s');
  const space = spaceIndex === -1 ? undefined : Number(args[spaceIndex + 1]);
  const rest = args.filter((_, index) => spaceIndex === -1 || (index !== spaceIndex && index !== spaceIndex + 1));
  const [source, target] = rest;
  const json = JSON.stringify(JSON5.parse(files[source] ?? ''), null, space);
  return target === undefined ? { stdout: json, files: {} } : { stdout: '', files: { [target]: json } };
};

